sed and tracked elsewhere. Streamlines the codebase and reduces clutter.","tree":{"sha":"64b436265f6b2f4cb9544a545d5e4e222c643f1c","url":"https://api.github.com/repos/filip-herceg/ReViewPoint/git/trees/64b436265f6b2f4cb9544a545d5e4e222c643f1c"},"url":"https://api.github.com/repos/filip-herceg/ReViewPoint/git/commits/bab15b447d37280ec5949f610bf40c50091ffcb8","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/92739281?v=4","events_url":"https://api.github.com/users/filip-herceg/events{/privacy}","followers_url":"https://api.github.com/users/filip-herceg/followers","following_url":"https://api.github.com/users/filip-herceg/following{/other_user}","gists_url":"https://api.github.com/users/filip-herceg/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/filip-herceg","id":92739281,"login":"filip-herceg","node_id":"U_kgDOBYcW0Q","organizations_url":"https://api.github.com/users/filip-herceg/orgs","received_events_url":"https://api.github.com/users/filip-herceg/received_events","repos_url":"https://api.github.com/users/filip-herceg/repos","site_admin":false,"starred_url":"https://api.github.com/users/filip-herceg/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/filip-herceg/subscriptions","type":"User","url":"https://api.github.com/users/filip-herceg","user_view_type":"public"},"html_url":"https://github.com/filip-herceg/ReViewPoint/commit/bab15b447d37280ec5949f610bf40c50091ffcb8","node_id":"C_kwDOOmgo49oAKGJhYjE1YjQ0N2QzNzI4MGVjNTk0OWY2MTBiZjQwYzUwMDkxZmZjYjg","parents":[{"html_url":"https://github.com/filip-herceg/ReViewPoint/commit/aa351136644c5cf941a5792e9216a92f2a3b09f0","sha":"aa351136644c5cf941a5792e9216a92f2a3b09f0","url":"https://api.github.com/repos/filip-herceg/ReViewPoint/commits/aa351136644c5cf941a5792e9216a92f2a3b09f0"}],"sha":"bab15b447d37280ec5949f610bf40c50091ffcb8","url":"https://api.github.com/rep